import{_ as s,o as t,c as i,a2 as a}from"./chunks/framework.LX5S0jbT.js";const k=JSON.parse('{"title":"Environment Variables","description":"","frontmatter":{},"headers":[],"relativePath":"environment-variables.md","filePath":"environment-variables.md"}'),o={name:"environment-variables.md"};function d(n,e,r,l,h,c){return t(),i("div",null,[...e[0]||(e[0]=[a(`<h1 id="environment-variables" tabindex="-1">Environment Variables <a class="header-anchor" href="#environment-variables" aria-label="Permalink to &quot;Environment Variables&quot;">​</a></h1><p>Pi uses environment variables in three ways:</p><ul><li>Variables such as <code>PI_OFFLINE</code> configure the Pi process.</li><li>Pi sets process markers so child processes can identify Pi as the launching agent.</li><li>Commands run by the LLM-callable shell tools receive <code>PI_*</code> variables describing the current session.</li></ul><p>Provider API-key variables are documented separately in <a href="./providers.html#use-an-api-key-from-the-environment">Providers</a>.</p><h2 id="process-marker" tabindex="-1">Process Marker <a class="header-anchor" href="#process-marker" aria-label="Permalink to &quot;Process Marker&quot;">​</a></h2><p>The CLI and RPC entry points set two process markers:</p><ul><li><code>AI_AGENT=pi</code> is a generic marker that lets tooling identify Pi as the agent that launched the process.</li><li><code>PI_CODING_AGENT=true</code> is Pi-specific and lets child processes detect that they run inside Pi.</li></ul><p>Child processes inherit both markers. They are not session-specific and are not set automatically when Pi is embedded through the SDK.</p><h2 id="shell-tool-session-environment" tabindex="-1">Shell Tool Session Environment <a class="header-anchor" href="#shell-tool-session-environment" aria-label="Permalink to &quot;Shell Tool Session Environment&quot;">​</a></h2><p>Commands run by the <code>bash</code> and <code>powershell</code> tools receive the current Pi session state:</p><table tabindex="0"><thead><tr><th>Variable</th><th>Description</th></tr></thead><tbody><tr><td><code>PI_SESSION_ID</code></td><td>Current session ID</td></tr><tr><td><code>PI_SESSION_FILE</code></td><td>Absolute path to the current session JSONL file; unset for ephemeral sessions</td></tr><tr><td><code>PI_PROVIDER</code></td><td>Currently selected model provider</td></tr><tr><td><code>PI_MODEL</code></td><td>Currently selected model ID</td></tr><tr><td><code>PI_REASONING_LEVEL</code></td><td>Current effective reasoning level: <code>off</code>, <code>minimal</code>, <code>low</code>, <code>medium</code>, <code>high</code>, <code>xhigh</code>, or <code>max</code></td></tr></tbody></table><p>The values are resolved when each command starts. Switching models or changing the reasoning level therefore affects the next shell command without restarting Pi. <code>PI_PROVIDER</code> and <code>PI_MODEL</code> identify the selected Pi model, not a different upstream model that a router may choose internally.</p><p>When asked which model or provider is running, inspect these variables instead of inferring the answer from the system prompt:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">printf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;%s/%s\\n&#39;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$PI_PROVIDER</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$PI_MODEL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">printf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;reasoning=%s session=%s\\n&#39;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$PI_REASONING_LEVEL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$PI_SESSION_ID</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span></span></code></pre></div><p>The session file can be inspected directly when the session is persistent:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [ </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-n</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$PI_SESSION_FILE</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ]; </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">then</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  tail</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$PI_SESSION_FILE</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">fi</span></span></code></pre></div><p>These variables are injected into the LLM-callable <code>bash</code> and <code>powershell</code> tools. They are not injected into user-entered <code>!</code> or <code>!!</code> commands.</p><h3 id="custom-shell-tools" tabindex="-1">Custom Shell Tools <a class="header-anchor" href="#custom-shell-tools" aria-label="Permalink to &quot;Custom Shell Tools&quot;">​</a></h3><p>Tools created with <code>createBashTool()</code> or <code>createPowerShellTool()</code> expose the session environment by default when registered with Pi. Injection happens before <code>spawnHook</code>, so a hook receives the variables in <code>ctx.env</code>:</p><div class="language-typescript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">typescript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> bashTool</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> createBashTool</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(cwd, {</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  spawnHook</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: (</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">ctx</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ({</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    ...</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ctx,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    env: { </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">...</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ctx.env, CI: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;1&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> },</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }),</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">});</span></span></code></pre></div><p>Disable session metadata independently of the spawn hook:</p><div class="language-typescript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">typescript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> powershellTool</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> createPowerShellTool</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(cwd, {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  exposeSessionEnvironment: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  spawnHook</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: (</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">ctx</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ctx,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">});</span></span></code></pre></div><p>When disabled, Pi removes inherited values for these variables so nested Pi processes do not expose stale parent-session metadata.</p><h2 id="pi-process-configuration" tabindex="-1">Pi Process Configuration <a class="header-anchor" href="#pi-process-configuration" aria-label="Permalink to &quot;Pi Process Configuration&quot;">​</a></h2><p>These variables are read by Pi itself:</p><table tabindex="0"><thead><tr><th>Variable</th><th>Description</th></tr></thead><tbody><tr><td><code>PI_CODING_AGENT_DIR</code></td><td>Override the config directory; default is <code>~/.pi/agent</code></td></tr><tr><td><code>PI_CODING_AGENT_SESSION_DIR</code></td><td>Override session storage; overridden by <code>--session-dir</code></td></tr><tr><td><code>PI_PACKAGE_DIR</code></td><td>Override the package directory, useful for Nix/Guix store paths</td></tr><tr><td><code>PI_OFFLINE</code></td><td>Disable automatic network activity, including model catalog refreshes</td></tr><tr><td><code>PI_SKIP_VERSION_CHECK</code></td><td>Disable the <code>pi.dev</code> latest-version request</td></tr><tr><td><code>PI_TELEMETRY</code></td><td>Override install/update telemetry and provider attribution headers: <code>1</code>/<code>true</code>/<code>yes</code> or <code>0</code>/<code>false</code>/<code>no</code></td></tr><tr><td><code>PI_CODEMODE_MAX_WORKERS</code></td><td>Maximum codemode workers alive at once across all sessions in the process; default <code>2</code>. Each worker&#39;s script may use up to 256 MB. Raise it when one process runs several sessions, such as in-process subagents. Further scripts wait for a free worker. See <a href="./codemode.html">Codemode</a></td></tr><tr><td><code>PI_CACHE_RETENTION</code></td><td>Set to <code>long</code> for extended provider prompt caching where supported</td></tr><tr><td><code>PI_SHARE_VIEWER_URL</code></td><td>Override the base URL used by <code>/share</code></td></tr><tr><td><code>PI_RADIUS_GATEWAY</code></td><td>Override the Radius gateway origin used by <code>/bug</code> uploads</td></tr><tr><td><code>PI_CLEAR_ON_SHRINK</code></td><td>Set to <code>1</code> to clear empty rows when rendered content shrinks; the <code>terminal.clearOnShrink</code> setting takes precedence. See <a href="./settings.html">Settings</a></td></tr><tr><td><code>PI_HARDWARE_CURSOR</code></td><td>Set to <code>1</code> to show the hardware cursor; see <a href="./terminal-setup.html">Terminal setup</a></td></tr><tr><td><code>PI_CLIPBOARD_OSC52</code></td><td>Set to <code>1</code> to also send copied text to the terminal with OSC 52 after the local clipboard write, as Pi does over SSH. Use it when a remote client reaches Pi without SSH variables, such as a multiplexer attached from another machine or a remote IDE daemon</td></tr><tr><td><code>PI_HYPERLINKS</code></td><td>Override OSC 8 hyperlink detection with <code>1</code>, <code>0</code>, or <code>auto</code></td></tr><tr><td><code>PI_PROGRAM_STATUS</code></td><td>Override OSC 7501 program status detection: <code>1</code> always reports, <code>0</code> never reports; otherwise Pi reports only after the terminal confirms support. See <a href="./terminal-setup.html#program-status">Terminal setup</a></td></tr><tr><td><code>PI_IMAGE_PROTOCOL</code></td><td>Override inline image detection with <code>kitty</code>, <code>iterm2</code>, <code>none</code>, or <code>auto</code></td></tr><tr><td><code>PI_TRUE_COLOR</code></td><td>Override truecolor detection with <code>1</code>, <code>0</code>, or <code>auto</code></td></tr><tr><td><code>PI_TUI_ESC_TIMEOUT</code></td><td>How long to wait after a lone ESC before treating it as Escape, in milliseconds; defaults to <code>100</code> over SSH and <code>10</code> otherwise. Increase if Alt-key input is misread as Escape</td></tr><tr><td><code>VISUAL</code>, <code>EDITOR</code></td><td>External editor fallback when <code>externalEditor</code> is unset</td></tr><tr><td><code>HTTP_PROXY</code>, <code>HTTPS_PROXY</code></td><td>Proxy outbound HTTP requests</td></tr></tbody></table><p>Provider credentials such as <code>ANTHROPIC_API_KEY</code>, <code>OPENAI_API_KEY</code>, and provider-specific configuration are listed in <a href="./providers.html#use-an-api-key-from-the-environment">Providers</a>.</p>`,27)])])}const E=s(o,[["render",d]]);export{k as __pageData,E as default};
